/*
 * prog26_wildcard_match.c
 *
 * Original behaviour (observed from the binary):
 *
 *   prog26_wildcard_match <pattern> <text>
 *
 *   * pattern may contain the wild‑cards '*' (any sequence, possibly empty)
 *     and '?' (any single character).
 *   * The program prints "MATCH"  if the pattern matches the whole text,
 *     otherwise it prints "NO_MATCH".
 *   * If the number of arguments is not exactly three, it prints "USAGE".
 *
 * The implementation below reproduces the exact observable behaviour
 * (output strings and exit code) while using a clear, idiomatic C
 * dynamic‑programming algorithm that matches the logic discovered in the
 * decompiled state‑machine.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* -------------------------------------------------------------
 * wildcard_match
 *
 * Returns true (1) if `pattern` matches the whole `text`.
 * The pattern may contain:
 *   '*' – matches any (possibly empty) sequence of characters
 *   '?' – matches any single character
 * ------------------------------------------------------------- */
static bool wildcard_match(const char *pattern, const char *text)
{
    size_t n = strlen(pattern);   /* pattern length  (columns) */
    size_t m = strlen(text);      /* text length     (rows)   */

    /* Allocate a (m+1) × (n+1) DP table, stored row‑major.
       dp[i][j] == true  ⇔  first i characters of text match
                           first j characters of pattern                */
    bool *dp = calloc((m + 1) * (n + 1), sizeof(bool));
    if (!dp) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }

    /* Helper macro to index the flat array */
#define DP(i, j) dp[(i) * (n + 1) + (j)]

    DP(0, 0) = true;                     /* empty pattern matches empty text */

    /* First row – empty text, pattern may contain leading '*' only */
    for (size_t j = 1; j <= n; ++j) {
        if (pattern[j - 1] == '*')
            DP(0, j) = DP(0, j - 1);
        else
            DP(0, j) = false;
    }

    /* Remaining rows – fill DP table */
    for (size_t i = 1; i <= m; ++i) {
        DP(i, 0) = false;                /* non‑empty text cannot match empty pattern */

        for (size_t j = 1; j <= n; ++j) {
            char pc = pattern[j - 1];
            char tc = text[i - 1];

            if (pc == '*') {
                /* '*' matches empty sequence (DP[i][j‑1]) or
                 * consumes one character from text (DP[i‑1][j])   */
                DP(i, j) = DP(i, j - 1) || DP(i - 1, j);
            } else if (pc == '?' || pc == tc) {
                DP(i, j) = DP(i - 1, j - 1);
            } else {
                DP(i, j) = false;
            }
        }
    }

    bool result = DP(m, n);
    free(dp);
    return result;
}

/* -------------------------------------------------------------
 * main
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
